begin;
select no_plan();
select ok(not has_function_privilege('authenticated','public.openai_chat_relay(uuid,uuid,text,text,text)','execute'),'browser cannot use privileged relay');
select ok(not has_table_privilege('service_role','private.openai_chat_calls','select'),'relay claims are private');
insert into auth.users(id,email,email_confirmed_at,is_anonymous)values('aaaaaaaa-0000-4000-8000-000000000001','relay@example.invalid',now(),false),('aaaaaaaa-0000-4000-8000-000000000002','relay2@example.invalid',now(),false);
insert into private.credit_price_versions select 'relay-test',prices||'[{"operation":"chat","provider":"gpt-6-astra","model":"gpt-6-astra","resolution":"","unitMinor":17,"label":"Synthetic relay"}]',now()from private.credit_price_versions where version=(select version from private.credit_settings);
update private.credit_settings set version='relay-test',enabled=true;
update private.provider_runtime_config set enabled=true where provider='gpt-6-astra';
create function pg_temp.relay(a text,u uuid default 'aaaaaaaa-0000-4000-8000-000000000001',m text default 'gpt-6-astra',c text default null)returns jsonb language sql as $$select public.openai_chat_relay(u,'bbbbbbbb-0000-4000-8000-000000000001',m,a,c)$$;
select throws_ok($$select pg_temp.relay('claim')$$,'P0001','relay_not_authorized','unfunded request cannot invoke model');
create temporary table relay_fixture as select private.credit_dispatch_before_token('aaaaaaaa-0000-4000-8000-000000000001','text_start','{"requestId":"bbbbbbbb-0000-4000-8000-000000000001","operation":"chat","model":"gpt-6-astra","billing":{"version":"relay-test","totalMinor":17},"input":{"message":"frozen original"}}')op;
select throws_ok($$select pg_temp.relay('claim')$$,'P0001','relay_not_authorized','reservation alone cannot invoke before claim');
select public.credit_dispatch('aaaaaaaa-0000-4000-8000-000000000001','text_claim','{"requestId":"bbbbbbbb-0000-4000-8000-000000000001"}');
insert into public.timeline_items(session_id,kind,role,text)select(op#>>'{started,session,id}')::uuid,'message','user','later unrelated message'from relay_fixture;
select throws_ok($$select pg_temp.relay('claim','aaaaaaaa-0000-4000-8000-000000000002')$$,'P0001','relay_not_authorized','other account cannot claim request');
select throws_ok($$select pg_temp.relay('claim','aaaaaaaa-0000-4000-8000-000000000001','gpt-6.1-sol')$$,'P0001','relay_not_authorized','model must match frozen operation');
create temporary table relay_claim as select pg_temp.relay('claim')v;
select is((select v#>>'{messages,0,content}'from relay_claim),'frozen original','relay reconstructs funded original prompt');
select is((select jsonb_array_length(v->'messages')from relay_claim),1,'later session messages cannot change original context');
select throws_ok($$select pg_temp.relay('claim')$$,'P0001','relay_result_pending','ambiguous repeat cannot buy another response');
select pg_temp.relay('result','aaaaaaaa-0000-4000-8000-000000000001','gpt-6-astra','saved reply');
select is(pg_temp.relay('claim')->>'action','replay','persisted reply is replayed');
select is((select status from private.credit_operations where business_key='text:bbbbbbbb-0000-4000-8000-000000000001'),'result','Edge result remains available to existing finalizer');
select throws_ok($$select pg_temp.relay('result','aaaaaaaa-0000-4000-8000-000000000001','gpt-6-astra','different')$$,'P0001','idempotency_conflict','completed response cannot be changed');
select is((select jsonb_array_length(messages)from private.openai_chat_calls),0,'completed relay clears copied history');
update private.openai_chat_calls set messages='[{"role":"user","content":"unknown-call fixture"}]';
update public.sessions set status='deleting',deleted_at=now()where id=(select(op#>>'{started,session,id}')::uuid from relay_fixture);
select is((select jsonb_array_length(messages)from private.openai_chat_calls),0,'session closure clears pending copied history');
delete from auth.users where id='aaaaaaaa-0000-4000-8000-000000000001';
select is((select count(*)::int from private.openai_chat_calls),0,'account cascade clears relay state');
select finish();rollback;
